bug_report:
using concept type-constraint declared in nested namespace causes incorrect compilation error
#include <concepts>
#include <ranges>
#include <vector>
namespace ns1 {
template <typename T, typename V>
concept RangeV = std::ranges::range<T> && std::same_as<std::ranges::range_value_t<T>, V>;
}
namespace ns2 {
ns1::RangeV<int> auto fn() { return std::vector<int>{}; }      // compiles
struct X {
    ns1::RangeV<int> auto fn() { return std::vector<int>{}; }  // fails to compile (bug!)
};
using ns1::RangeV;
struct Y {
    RangeV<int> auto fn() { return std::vector<int>{}; }       // compiles
};
}

